pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    uint constant TICKET = 10;

    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(address player) public {
        vm.assume(player != address(0));

        vm.deal(player, 1 ether);

        vm.prank(player);
        c.play{value: TICKET}();

        uint p = c.pot();
        assertTrue(p == 0 || p == TICKET);
    }
}
